package com.univmar.quotation;
import com.univmar.common.api.ApiException; import com.univmar.customer.domain.*; import com.univmar.project.domain.*; import com.univmar.quotation.api.QuotationDtos.*; import com.univmar.quotation.domain.*; import com.univmar.rfq.domain.*; import com.univmar.user.domain.UserRepository; import java.math.*; import java.time.*; import java.util.*; import org.springframework.data.domain.*; import org.springframework.http.HttpStatus; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @Transactional public class QuotationService {private final QuotationRepository q;private final CustomerRepository c;private final ProjectRepository p;private final QuoteRequestRepository r;private final UserRepository users; public QuotationService(QuotationRepository q,CustomerRepository c,ProjectRepository p,QuoteRequestRepository r,UserRepository u){this.q=q;this.c=c;this.p=p;this.r=r;users=u;} public Response create(Input i){Customer cu=c.findById(i.customerId()).orElseThrow(()->nf("CUSTOMER_NOT_FOUND"));Project pr=p.findById(i.projectId()).orElseThrow(()->nf("PROJECT_NOT_FOUND"));if(!pr.getCustomer().getId().equals(cu.getId()))throw bad("PROJECT_CUSTOMER_MISMATCH");QuoteRequest rf=i.rfqId()==null?null:r.findById(i.rfqId()).orElseThrow(()->nf("RFQ_NOT_FOUND"));if(rf!=null&&(!rf.getCustomer().getId().equals(cu.getId())||!rf.getProject().getId().equals(pr.getId())))throw bad("RFQ_REFERENCE_MISMATCH");Quotation x=new Quotation("QT-"+LocalDate.now().toString().replace("-","")+"-"+UUID.randomUUID().toString().substring(0,6).toUpperCase(),cu,pr,rf,actor(),i.expiryDate(),i.transport(),trim(i.paymentTerms()),trim(i.notes()),1);i.items().forEach(line->x.add(new QuotationItem(x,trim(line.materialName()),trim(line.variantLabel()),line.quantityM2(),line.unitPrice(),line.discountPercent(),line.taxPercent())));if(rf!=null)rf.transitionTo(RfqStatus.QUOTED);return out(q.save(x));} public Response update(UUID id,Input i){Quotation x=e(id);if(x.getStatus()!=QuotationStatus.DRAFT)throw bad("QUOTE_NOT_DRAFT");x.update(i.expiryDate(),i.transport(),trim(i.paymentTerms()),trim(i.notes()));return out(x);} public Response send(UUID id){Quotation x=e(id);if(x.getStatus()!=QuotationStatus.DRAFT)throw bad("QUOTE_NOT_DRAFT");if(x.getExpiryDate()==null||x.getExpiryDate().isBefore(LocalDate.now()))throw bad("INVALID_EXPIRY");x.status(QuotationStatus.SENT);return out(x);} public Response reject(UUID id){Quotation x=e(id);if(x.getStatus()!=QuotationStatus.SENT)throw bad("QUOTE_NOT_SENT");x.status(QuotationStatus.REJECTED);return out(x);} public Response expire(UUID id){Quotation x=e(id);if(x.getStatus()!=QuotationStatus.SENT)throw bad("QUOTE_NOT_SENT");x.status(QuotationStatus.EXPIRED);return out(x);} @Transactional(readOnly=true) public Response detail(UUID id){return out(e(id));}@Transactional(readOnly=true) public PageResult list(QuotationStatus status,Pageable page){return PageResult.from(q.findAll(page).map(this::out));} private Quotation e(UUID id){return q.findById(id).orElseThrow(()->nf("QUOTATION_NOT_FOUND"));}private Response out(Quotation x){return new Response(x.getId(),x.getNumber(),x.getCustomer().getId(),x.getCustomer().getName(),x.getProject().getId(),x.getProject().getName(),x.getRfq()==null?null:x.getRfq().getId(),x.getSalesAgent(),x.getExpiryDate(),x.getTransport(),x.getPaymentTerms(),x.getNotes(),x.getStatus(),x.getRevision(),x.getSubtotal(),x.getTaxTotal(),x.getGrandTotal(),x.getCreatedAt(),x.getItems().stream().map(a->new Line(a.getId(),a.getMaterialName(),a.getVariantLabel(),a.getQuantityM2(),a.getUnitPrice(),a.getDiscountPercent(),a.getTaxPercent(),a.net(),a.tax(),a.net().add(a.tax()))).toList());}private String actor(){var a=SecurityContextHolder.getContext().getAuthentication();try{return a==null?"System":users.findById(UUID.fromString(a.getName())).map(u->u.getEmail()).orElse("System");}catch(Exception e){return "System";}}private String trim(String s){return s==null||s.isBlank()?null:s.trim();}private ApiException nf(String c){return new ApiException(HttpStatus.NOT_FOUND,c,"Reference was not found.");}private ApiException bad(String c){return new ApiException(HttpStatus.CONFLICT,c,"The quotation cannot be changed in its current state.");}}
